@Service
public class OrderService { }

// Custom name: bean is now "orderSvc"
@Service("orderSvc")
public class OrderService { }

@Configuration
public class DatabaseConfig {
    // Bean name is "primaryDb" (method name)
    @Bean
    public DataSource primaryDb() {
        return new HikariDataSource();
    }

    // Custom name: bean is "reportsDatabase"
    @Bean(name = "reportsDatabase")
    public DataSource secondaryDb() {
        return new HikariDataSource();
    }
}

@Service
public class ReportService {
    private final DataSource dataSource;

    public ReportService(@Qualifier("reportsDatabase") DataSource ds) {
        this.dataSource = ds;  // Gets the secondaryDb bean
    }
}
