import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.stereotype.Service;

@Service
class OrderService {
    private final PaymentGateway gateway;
    public OrderService(PaymentGateway gateway) { this.gateway = gateway; }
}

@Service
class PaymentGateway {}

public class BeanDefinitionDemo {
    public static void main(String[] args) {
        var context = new AnnotationConfigApplicationContext("com.example");

        // Bean definition exists before bean instance is created
        var definition = context.getBeanDefinition("orderService");
        System.out.println("Bean class: " + definition.getBeanClassName());
        System.out.println("Scope: " + definition.getScope()); // singleton
        System.out.println("Lazy init: " + definition.isLazyInit()); // false

        // Now get the actual instance (created from the definition)
        var service = context.getBean(OrderService.class);
    }
}
