@Component
public class DatabaseSchemaInitializer {
    public DatabaseSchemaInitializer() {
        System.out.println("Creating database tables...");
        // Schema creation logic runs here
    }
}

@Service
@DependsOn("databaseSchemaInitializer")  // Wait for schema setup
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
        System.out.println("OrderService ready - tables exist");
    }

    public void createOrder(String item) {
        repository.save(new Order(null, item));  // Tables must exist
    }
}
